    },
    {
      "scene_number": 11,
      "caption": "Inside the cursed tower, a prisoner is found.",
      "visual_description": "A barred cell inside a circular room with chains on the walls, a lone figure in tattered clothes sitting on the floor, the party approaching cautiously.",
      "characters": ["rescued_prisoner", "map_reader", "scout", "magic_helper", "comic_official", "bridge_crosser"]
    },
    {
      "scene_number": 12,
      "caption": "The magic helper breaks the curse with a mirror shard.",
