      "characters": ["magic_helper", "rescued_prisoner", "map_reader", "scout", "comic_official", "bridge_crosser"]
    },
    {
      "scene_number": 13,
      "caption": "Armored patrols block the escape route.",
      "visual_description": "Three armored figures stand in a narrow hallway with swords drawn, their shields bearing the old royal crest, facing the party at close range.",
      "characters": ["armored_patrol", "map_reader", "scout", "magic_helper", "comic_official", "bridge_crosser", "rescued_prisoner"]
    },
    {
      "scene_number": 14,
      "caption": "The scout leads a detour through the kitchens.",
      "visual_description": "A smoke-blackened kitchen with overturned pots and a rusted iron stove, the scout pointing to a low door in the corner, the party following single file.",
      "characters": ["scout", "map_reader", "magic_helper", "comic_official", "bridge_crosser", "rescued_prisoner"]
    },
    {
      "scene_number": 15,
      "caption": "The bridge lever is found on a broken parapet.",
      "visual_description": "A stone parapet with a single lever, next to a torn banner, overlooking a wide chasm where a drawbridge is currently raised, the map reader examining the mechanism.",
      "characters": ["map_reader", "bridge_crosser", "scout", "magic_helper", "comic_official", "rescued_prisoner"]
    },
    {
      "scene_number": 16,
      "caption": "The comic official operates the lever.",
      "visual_description": "The comic official strains to push the heavy lever, his ledger tucked under one arm, as the drawbridge begins to lower with a great creak and rattle of chains.",
      "characters": ["comic_official", "map_reader", "scout", "magic_helper", "bridge_crosser", "rescued_prisoner"]
    },
    {
      "scene_number": 17,
      "caption": "The party races across the bridge.",
      "visual_description": "All characters run across a long stone bridge high above a river of mist, with arrows or shouts behind them, the far gate open and welcoming.",
      "characters": ["map_reader", "scout", "magic_helper", "comic_official", "bridge_crosser", "rescued_prisoner"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the forest as the city ruins fade behind.",
      "visual_description": "The group stands at the edge of a dark forest, looking back at the ruined city silhouetted against a setting sun, the rescued prisoner safe among them.",
      "characters": ["map_reader", "scout", "magic_helper", "comic_official", "bridge_crosser", "rescued_prisoner"]
    }
  ]
}
